def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[:] for row in grid]
    # Extend each edge ray only when its entire path to the border is clear.
    for r in range(r0, r1 + 1):
        for step in (-1, 1):
            path = list(range(c0 - 1, -1, -1)) if step < 0 else list(range(c1 + 1, w))
            if all(grid[r][c] == 0 for c in path):
                for c in path:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
        for step in (-1, 1):
            start = r0 - 1 if step < 0 else r1 + 1
            path = range(start, -1, -1) if step < 0 else range(start, h)
            if all(grid[r][c] == 0 for r in path):
                for r in path:
                    out[r][c] = 2
    return out
